from pathlib import Path
import re
roots=[Path('.skilled/skills/mcp-tooling'), Path('.skilled/skills/sk-doc')]
count=0
for root in roots:
    for p in root.rglob('*.md'):
        t=p.read_text(errors='ignore').splitlines()
        for i,l in enumerate(t):
            if l.strip()=='### Purpose':
                # find next ### heading
                j=i+1
                between=[]
                while j<len(t) and not t[j].startswith('### '):
                    between.append(t[j]); j+=1
                if j<len(t) and t[j].strip()=='### When to Use':
                    nonblank=[x for x in between if x.strip()]
                    # nonblank includes blank lines and maybe paragraphs
                    if len(nonblank)>2:
                        print(p, 'between lines', len(nonblank))
                        count+=1
print('count',count)
